// Edge-case vectors shared with ml/tests/test_sp_bef.py and lms-web sp_bef.test.ts
// (generated by ml/export_sp_bef_edge_cases.py, kept in sync by the ml copy-sync test).
//
//go:embed models/sp_bef_edge_cases.json
var embeddedEdgeCases []byte

// edgeNum decodes a JSON number or the strings "NaN", "Infinity", "-Infinity".
type edgeNum float64

func (n *edgeNum) UnmarshalJSON(b []byte) error {
	var s string
	if err := json.Unmarshal(b, &s); err == nil {
		switch s {
		case "NaN":
			*n = edgeNum(math.NaN())
		case "Infinity":
			*n = edgeNum(math.Inf(1))
		case "-Infinity":
			*n = edgeNum(math.Inf(-1))
		default:
			return fmt.Errorf("unexpected numeric string %q", s)
		}
		return nil
	}
	var f float64
	if err := json.Unmarshal(b, &f); err != nil {
		return err
	}
	*n = edgeNum(f)
	return nil
}

func edgeFloats(in []edgeNum) []float64 {
	out := make([]float64, len(in))
	for i, v := range in {
		out[i] = float64(v)
	}
	return out
}

type edgeStepArgs struct {
	PrevPosterior        edgeNum `json:"prev_posterior"`
	SegmentPrior         edgeNum `json:"segment_prior"`
	LLRFace              edgeNum `json:"llr_face"`
	RFace                edgeNum `json:"r_face"`
	LLRBeh               edgeNum `json:"llr_beh"`
	RBeh                 edgeNum `json:"r_beh"`
	LLRQuiz              edgeNum `json:"llr_quiz"`
	RQuiz                edgeNum `json:"r_quiz"`
	PrevHighSec          edgeNum `json:"prev_high_sec"`
	PrevIntervening      bool    `json:"prev_intervening"`
	CooldownRemainingSec edgeNum `json:"cooldown_remaining_sec"`
	DtSec                edgeNum `json:"dt_sec"`
	LLRGaze              edgeNum `json:"llr_gaze"`
	RGaze                edgeNum `json:"r_gaze"`
}

type edgeCaseDoc struct {
	Interp []struct {
		X        edgeNum   `json:"x"`
		XP       []float64 `json:"xp"`
		FP       []float64 `json:"fp"`
		Expected float64   `json:"expected"`
	} `json:"interp"`
	FrameReliability []struct {
		Args     []edgeNum `json:"args"`
		Expected float64   `json:"expected"`
	} `json:"frame_reliability"`
	GazeReliability []struct {
		Args     []edgeNum `json:"args"`
		Expected float64   `json:"expected"`
	} `json:"gaze_reliability"`
	Branch struct {
		Cfg   SPBEFBranchConfig `json:"cfg"`
		Cases []struct {
			Features []edgeNum `json:"features"`
			Expected []float64 `json:"expected"`
		} `json:"cases"`
	} `json:"branch"`
	Step []struct {
		CaseID   string            `json:"case_id"`
		Fusion   SPBEFFusionConfig `json:"fusion"`
		Args     edgeStepArgs      `json:"args"`
		Expected SPBEFStepResult   `json:"expected"`
	} `json:"step"`
}

func loadEdgeCases(t *testing.T) edgeCaseDoc {
	t.Helper()
	var doc edgeCaseDoc
	require.NoError(t, json.Unmarshal(embeddedEdgeCases, &doc), "must parse models/sp_bef_edge_cases.json")
	require.NotEmpty(t, doc.Step)
	return doc
}

func TestSPBEF_EdgeCaseVectorsMatchPythonAndTS(t *testing.T) {
	doc := loadEdgeCases(t)
	const tol = 1e-6

	for i, c := range doc.Interp {
		assert.InDelta(t, c.Expected, PiecewiseLinearInterp(float64(c.X), c.XP, c.FP), tol, "interp case %d", i)
	}
	for i, c := range doc.FrameReliability {
		a := edgeFloats(c.Args)
		assert.InDelta(t, c.Expected, ComputeFrameReliability(a[0], a[1], a[2], a[3], a[4]), tol, "frame reliability case %d", i)
	}
	for i, c := range doc.GazeReliability {
		a := edgeFloats(c.Args)
		assert.InDelta(t, c.Expected, ComputeGazeReliability(a[0], a[1], a[2], a[3]), tol, "gaze reliability case %d", i)
	}
	for i, c := range doc.Branch.Cases {
		raw, cal, llr := PredictLinearCalibratedBranch(edgeFloats(c.Features), doc.Branch.Cfg)
		assert.InDeltaSlice(t, c.Expected, []float64{raw, cal, llr}, tol, "branch case %d", i)
	}

	for _, c := range doc.Step {
		t.Run(c.CaseID, func(t *testing.T) {
			a := c.Args
			got := SPBEFStepWithGaze(
				float64(a.PrevPosterior), float64(a.SegmentPrior), float64(a.LLRFace), float64(a.RFace),
				float64(a.LLRBeh), float64(a.RBeh), float64(a.LLRQuiz), float64(a.RQuiz),
				c.Fusion, float64(a.PrevHighSec), a.PrevIntervening, float64(a.CooldownRemainingSec), float64(a.DtSec),
				float64(a.LLRGaze), float64(a.RGaze),
			)
			exp := c.Expected
			assert.Equal(t, exp.Level, got.Level, "level")
			assert.Equal(t, exp.IsConfused, got.IsConfused, "is_confused")
			assert.Equal(t, exp.ShouldIntervene, got.ShouldIntervene, "should_intervene")
			pairs := map[string][2]float64{
				"prior_prob":             {exp.PriorProb, got.PriorProb},
				"posterior_prob":         {exp.PosteriorProb, got.PosteriorProb},
				"llr_face":               {exp.LLRFace, got.LLRFace},
				"llr_quiz":               {exp.LLRQuiz, got.LLRQuiz},
				"llr_gaze":               {exp.LLRGaze, got.LLRGaze},
				"r_face":                 {exp.RFace, got.RFace},
				"r_quiz":                 {exp.RQuiz, got.RQuiz},
				"contrib_face":           {exp.ContribFace, got.ContribFace},
				"contrib_quiz":           {exp.ContribQuiz, got.ContribQuiz},
				"contrib_gaze":           {exp.ContribGaze, got.ContribGaze},
				"segment_prior":          {exp.SegmentPrior, got.SegmentPrior},
				"high_duration_sec":      {exp.HighDurationSec, got.HighDurationSec},
				"cooldown_remaining_sec": {exp.CooldownRemainingSec, got.CooldownRemainingSec},
			}
			for name, p := range pairs {
				assert.InDelta(t, p[0], p[1], tol, name)
				assert.False(t, math.IsNaN(p[1]), "%s must not be NaN", name)
			}
		})
	}
}

// Regression: with the shipped theta_off = 0.25 the former fixed `mild` floor (p >= 0.25) coincided with
// theta_off, so `mild` was unreachable.
func TestSPBEF_MildLevelReachableWithShippedParams(t *testing.T) {
	p := newIsolatedPredictor(t)
	fus := p.SPBEFConfig().Fusion
	mildP := (SPBEFMildThetaOffRatio*fus.ThetaOff + fus.ThetaOff) / 2
	assert.Equal(t, "mild", SPBEFConfusionLevel(mildP, fus.ThetaOn, fus.ThetaOff, 1.0))
	assert.Equal(t, "none", SPBEFConfusionLevel(SPBEFMildThetaOffRatio*fus.ThetaOff-1e-6, fus.ThetaOn, fus.ThetaOff, 1.0))
	assert.Equal(t, "moderate", SPBEFConfusionLevel(fus.ThetaOff, fus.ThetaOn, fus.ThetaOff, 1.0))
	assert.Equal(t, "high", SPBEFConfusionLevel(fus.ThetaOn, fus.ThetaOn, fus.ThetaOff, 1.0))

	// End to end through the step function: posterior 0.224 with the shipped fusion block.
	step := SPBEFStep(0.2, 0.2, 0, 1, 0, 0, 0, 0, fus, 0, false, 0, 5)
	require.Less(t, step.PosteriorProb, fus.ThetaOff)
	assert.Equal(t, "mild", step.Level)
}
